import json

with open(SUN_JS, 'r', encoding='utf-8') as f:
    content = f.read()

# We want to insert Taurus into signs: { ... }
# Look for signs: {
signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    
    # Format taurus data
    taurus_json = "      Taurus: " + json.dumps(taurus_data, indent=8) + ","
    
    new_content = content[:insertion_point] + "\n" + taurus_json + content[insertion_point:]
    
    with open(SUN_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Sun in Taurus to sun.js")
else:
    print("Could not find signs object in sun.js")
